#include "bits/stdc++.h"using namespace std; #define int long long#define ll long long#define MOD 998244353#define all(v) v.begin(), v.end()#define rall(v) v.rbegin(), v.rend()#define pb push_back#define sz(a) (int)a.size()const int MAXN = 1000000;int fact[MAXN+1], invfact[MAXN+1]; int modmul(int a,int b){return ((a%MOD)*(b%MOD))%MOD;}int modpow(int base,int p){ int ans=1; base%=MOD;   while(p){if(p%2==1){ ans= modmul(base,ans);}  base=modmul(base,base); p/=2;}return ans;}int moddiv(int a , int b){return modmul(a,modpow(b,MOD-2));};int modadd(int a, int b) {return ((a % MOD) + (b % MOD)) % MOD;}int modsub(int a, int b) {return ((a % MOD) - (b % MOD) + MOD) % MOD;}int modinv(int a) { return modpow(a, MOD - 2);}void precompute() { fact[0] = 1;for (int i = 1; i <= MAXN; i++) { fact[i] = modmul(fact[i-1], i);  } invfact[MAXN] = modinv(fact[MAXN]); for (int i = MAXN-1; i >= 0; i--) {invfact[i] = modmul(invfact[i+1], i+1);}}int nCr(int n, int r) { if (r < 0 || r > n) return 0; return modmul(fact[n], modmul(invfact[r], invfact[n-r]));}vector<int> sieve(int n) {int*arr = new int[n + 1](); vector<int> vect; for (int i = 2; i <= n; i++)if (arr[i] == 0) {vect.push_back(i); for (int j = 2 * i; j <= n; j += i)arr[j] = 1;} return vect;}  ll gcd(ll a, ll b) {if (b > a) {return gcd(b, a);} if (b == 0) {return a;} return gcd(b, a % b);}  ll ____lcm(ll a,ll b){    return (a/gcd(a,b))*b;}const int N = 1e6;vector<int>prime(N+1,true);vector<int>spf(N+1,1e9);void sieveandspf(){    prime[0]=prime[1]=false;    for(int i=2;i<=N;i++){        if(prime[i]){            spf[i]=i;            for(int j=i*i;j<=N;j+=i){                prime[j]=false;                spf[j]=min(spf[j],i);            }        }    }}  int power(int base, int exp){    int res = 1;    while(exp--) res *= base;    return res;} vector<pair<int,int>> pf(int n){    vector<pair<int,int>> ans;     while(n != 1){        int p = spf[n];        int ct = 0;         while(n % p == 0){            ct++;            n /= p;        }         ans.push_back({p, ct});    }    return ans;} void solve(){     int n;    cin >> n;     vector<int> v(n);    for(auto &x : v) cin >> x;     for(auto x : v){         int sigma = 1;         auto fact = pf(x);         for(auto &pr : fact){            int p = pr.first;            int k = pr.second;             int mul = (power(p, k+1) - 1) / (p - 1);            sigma *= mul;        }         int sumProper = sigma - x;         if(sumProper > x){            cout << "abundant\n";        }        else if(sumProper < x){            cout << "deficient\n";        }        else{            cout << "perfect\n";        }    }} int32_t main() {    ios_base::sync_with_stdio(0);    cin.tie(0);    cout.tie(0);    int t = 1;    sieveandspf();    // precompute();    // cin >> t;    while (t--) {        solve();    }}